\label{def:labeled} ~ \begin{enumerate}
    \item A \emph{labeled surface} is a cone spherical surface\ whose cone points are labeled as $p_1,\cdots,p_n$ such that $p_i$ has cone angle of $2\pi \theta_i$, for $i=1,\cdots,n$.
    \item Let $\Sigma_k\ (k=1,2)$ be two labeled cone spherical surface s, with cone points labeled as $p^k_i, i=1,\cdots,n$. They are \emph{equivalent with label} if there exists an orientation-preserving isometry $I:\Sigma_1 \to \Sigma_2$ such that $I(p^1_i)=p^2_i$ for all $i$.
    \item The \emph{labeled moduli space} \textcolor{black}{$\mathcal{M}sph_{g,n}(\vec{\theta})$} is all equivalence classes of genus $g$ labeled surfaces with the given angle vector $\vec{\theta}$.
    \end{enumerate}

    Let $\vec{\theta}=(\theta_1, \cdots, \theta_n) \in \mathbb{R}_+^N$ be an angle vector with $\theta_i\neq 1$. A \emph{(topological) type partition} is a partition $\textcolor{black}{\vec{T}}=( E, O, N )$ of $\{1,\cdots,n\}$ satisfying that

\begin{itemize}
    \item $\forall i\in E, \theta_{i}\in \mathbb{Z}_{>1}$;
    \item $\forall j\in O, \theta_{j}\in \frac12 + \mathbb{Z}$.
\end{itemize}
    Let $ \#E=n_E, \#O=n_O, \#N=n_N $, then $n_E + n_O + n_N = n$.

    A foliated surface $(\Sigma;F,G)$ is \emph{of type partition $\vec{T}$}, if $p_i$ is a zero with index $(2-2\theta_i)$ for all $i \in E \cup O$, and $p_k$ is a pole for all $k \in N$.

\label{def:moduli_D}
    Let $\vec{T}$ be a type partition as above.
    \begin{enumerate}
    \item The moduli space \textcolor{black}{$\mathcal{M}sph^D_{g,n}(\vec{\theta})$} is the set of all equivalent classes of \textcolor{black}{strict dihedral} cone spherical surface s in $\mathcal{M}sph_{g,n}(\vec{\theta})$.
    \item \textcolor{black}{$\mathcal{M}sphF_{g,n}^D(\vec{\theta})$} is the set of all foliated strict dihedral surfaces $(\Sigma;F,G)$ with $\Sigma\in\mathcal{M}sph^D_{g,n}(\vec{\theta})$.
    \item $\textcolor{black}{\mathcal{M}sphF_{g,n}^D(\vec{\theta};\vec{T})} \subset \mathcal{M}sphF_{g,n}^D(\vec{\theta})$ is the set of foliated strict dihedral surfaces of type partition $\vec{T}$.
    \item $\textcolor{black}{\mathcal{M}sph_{g,n}^D(\vec{\theta};\vec{T})} :=\{ \Sigma \ \lvert\ (\Sigma;F,G)\in \mathcal{M}sphF_{g,n}^D(\vec{\theta};\vec{T}) \}$ is the set of all equivalent classes of (unfoliated) strict dihedral surfaces of type partition $\vec{T}$.
\end{enumerate}

\begin{equation}\label{eq:moduli_spaces_D} \begin{gathered}
