\label{def:cnnct_mtr}
    The \emph{connection matrix} \textcolor{black}{$\mathbf{M}$} of $(\Sigma;F,G)$ is an $m \times b$ matrix with all entries in $\{0,1,2\}$, determined by the following:
    \begin{itemize}
        \item if both vertices of bigon $B_j$ are glued to one pole $q_i$, then $\mathbf{M}_{ij}:=2$ ;
        \item if vertices of $B_j$ are glued to different poles $q_i\neq q_{i'}$, then $\mathbf{M}_{ij}=\mathbf{M}_{i'j}:=1$;
        \item all the other entries are $0$.
    \end{itemize}

\begin{equation}\label{eq:width_constrain}
    \vec{C} = \mathbf{M}  \vec{W}.
\end{equation}

\label{prop:rank} For generic foliated surface $(\Sigma;F,G)$, 
\begin{enumerate}
    \item $\mathrm{rank}(\mathbf{M}) \geq m-1$;
    \item the foliation pair $(F,G)$ is orientable if and only if $\mathrm{rank}(\mathbf{M}) = m-1$.
\end{enumerate}

For generic $(\Sigma;F,G)$, its connection matrix $\mathbf{M}$ is path-connected in the following sense: for any two non-zero elements $\mathbf{M}_{ij}, \mathbf{M}_{kl}$, there exists a finite sequence $(i_0,j_0), (i_1,j_1), \cdots, (i_N, j_N)$ such that
\begin{itemize}
    \item $(i_0,j_0)=(i,j), (i_N, j_N)=(k,l)$;
    \item $(i_{t-1},j_{t-1}), (i_{t},j_{t})$ have exactly one same component for all $t=1,\cdots,N$;
    \item all entries $\mathbf{M}_{(i_{t},j_{t})}$ are non-zero.
\end{itemize}

